    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-APPA-005",
      "what_failed": "Inferring defensive adjustments from play-type labels",
      "why": "LABEL_ERROR: inferred labels cannot separate real defensive change from offensive execution; near-uniform transitions indicate noise."
    },
    {
      "id": "FAM:SF-APPS-085",
      "what_failed": "Split-half reliability of a derived player-season trait (connector quality)",
      "why": "MEASURE_RELIABILITY: split-half correlation too low (r=0.215) to treat the trait as stable; most variance is within-player."
    }
  ],
  "evidence_establishes": [
    "Deriving stable defensive traits from play-by-play data is prone to measurement error (APPA-005).",
    "Even with moderate sample sizes (~100 units), split-half reliability of derived performance metrics can be too low to support a stable trait (APPS-085).",
    "A split-half design can detect insufficient reliability, but does not guarantee that a different metric would fare better."
